// One Slack message for the whole list, oldest due date first.
const actions = $input.all().map((i) => i.json).filter((a) => a && a.title);

if (actions.length === 0) {
  return [{ json: { text: ':white_check_mark: No overdue TeamRetro actions this week. Nice work!' } }];
}

const lines = actions.map((a) => {
  const owners = (a.assignedTo || []).map((u) => u.name || u.email).join(', ') || 'unassigned';
  const team = a.team ? a.team.name : 'unknown team';
  return `• *${a.title}* — ${owners} · ${team} · due ${a.due || 'n/a'}`;
});

return [{ json: { text: `:rotating_light: *${actions.length} overdue TeamRetro action(s)*\n${lines.join('\n')}` } }];
